const searchConfirmedTickets = `-- name: SearchConfirmedTickets :many
SELECT t.id, b.created_at AS cursor_created_at, b.id AS cursor_id
FROM tickets t
  INNER JOIN bookings b ON b.id = t.booking_id
  INNER JOIN events e ON e.id = t.event_id
WHERE b.status = 'CONFIRMED'
  AND e.deleted_at IS NULL
  AND (
    $1::uuid = '00000000-0000-0000-0000-000000000000'::uuid
    OR (b.created_at, b.id) < ($2::timestamptz, $1::uuid)
  )
  AND (
    $3::text = ''
    OR b.contact_phone ILIKE '%' || $3::text || '%'
    OR COALESCE(b.upi_transaction_id, '') ILIKE '%' || $3::text || '%'
    OR EXISTS (
      SELECT 1
      FROM ticket_guests tg
      WHERE tg.ticket_id = t.id AND tg.name ILIKE '%' || $3::text || '%'
    )
  )
ORDER BY b.created_at DESC, b.id DESC
LIMIT $4
`

type SearchConfirmedTicketsParams struct {
	CursorID        uuid.UUID `json:"cursor_id"`
	CursorCreatedAt time.Time `json:"cursor_created_at"`
	SearchQuery     string    `json:"search_query"`
	PageLimit       int32     `json:"page_limit"`
}

type SearchConfirmedTicketsRow struct {
	ID              uuid.UUID `json:"id"`
	CursorCreatedAt time.Time `json:"cursor_created_at"`
	CursorID        uuid.UUID `json:"cursor_id"`
}

func (q *Queries) SearchConfirmedTickets(ctx context.Context, arg SearchConfirmedTicketsParams) ([]SearchConfirmedTicketsRow, error) {
	rows, err := q.db.Query(ctx, searchConfirmedTickets,
		arg.CursorID,
		arg.CursorCreatedAt,
		arg.SearchQuery,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchConfirmedTicketsRow{}
	for rows.Next() {
		var i SearchConfirmedTicketsRow
		if err := rows.Scan(&i.ID, &i.CursorCreatedAt, &i.CursorID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

